# פרק 15 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=15
TITLE='מבוא לפתרון בעיה משפטית'
SUM=[' <p>נסגור במיומנות המעשית המרכזית — כיצד ניגשים ל<strong>פתרון שאלה משפטית</strong> (קייס), הן במבחן והן בפרקטיקה.</p> <h3>15.1 שיטת ה-IRAC</h3> <p>מתודולוגיה מקובלת: <strong>Issue</strong> (זיהוי הבעיה/השאלה המשפטית) → <strong>Rule</strong> (איתור הכלל המשפטי הרלוונטי — חוק ופסיקה) → <strong>Application</strong> (יישום הכלל על עובדות המקרה — לב הניתוח) → <strong>Conclusion</strong> (מסקנה).</p> <h3>15.2 הדגש על היישום</h3> <p>השלב החשוב הוא ה<strong>יישום</strong>: לא די לצטט את הדין — יש <strong>להחילו על העובדות הקונקרטיות</strong>, לדון בטענות הצדדים, ולהכריע ביניהן.</p> <h3>15.3 טיפים</h3> <p>לזהות את <strong>כל</strong> הסוגיות, להבחין בין עיקר לטפל, ולבסס כל קביעה — תוך התייחסות לעמדות נוגדות.</p> <h3>15.4 נקודות מפתח למבחן</h3> <ul><li>IRAC: בעיה → כלל → יישום → מסקנה.</li><li>הלב הוא היישום על העובדות, לא ציטוט הדין.</li><li>לזהות את כל הסוגיות ולבסס כל קביעה.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('בג״ץ 2624/97 רונאל נ׳ ממשלת ישראל, פ״ד נא(3) 71', 'עתירה לבג״ץ שבה נדונה דרישת מיצוי ההליכים — פנייה מוקדמת לרשות ומתן שהות לתשובתה לפני הגשת עתירה.', 'נפסק שגם כשהרשות עלולה להתעכב בתשובתה, על הפונה לתת לה שהות סבירה, לפי הנסיבות, לבחון את פנייתו. מיצוי הליכים הוא עילת סף: עתירה שלא עמדה בה עלולה להידחות בלי דיון לגופה. לקח שיטתי: בודקים את הסף לפני הגוף.'), ('בג״ץ 525/84 חטיב נ׳ בית הדין הארצי לעבודה, פ״ד מ(1) 673', 'עתירה נגד פסק דין של בית הדין הארצי לעבודה, שבה נדרשה השאלה באיזה היקף בג״ץ מתערב בהכרעותיו.', 'נקבע שבג״ץ אינו יושב כערכאת ערעור על בתי הדין לעבודה, ומתערב רק כשנפלה טעות משפטית מהותית ושיקולי צדק מחייבים התערבות. ההלכה מצוטטת עד היום. לקח שיטתי: לפני שמנתחים את גוף הסוגיה מזהים איזו שאלה בדיוק הגוף המכריע שואל.'), ('רע״א 4224/04 בית ששון בע״מ נ׳ שיכון עובדים והשקעות בע״מ, פ״ד נט(6) 625', 'דיון בשאלה אם בעל דין רשאי לטעון בהליך אחד טענה הסותרת טענה שטען בהליך קודם.', 'נקבעו תנאי ההשתק השיפוטי: בעל דין שטען טענה בהליך קודם, והטענה התקבלה באותו הליך, מנוע מלטעון טענה הפוכה בהליך מאוחר — גם אם אינו מראה שזכה בסופו של המשפט. לקח שיטתי: חלופות מותרות, אך לא "קפיצה" בין עמדות סותרות כדי להרוויח פעמיים.'), ('ע״א 2599/13 הרמן נ׳ עלדור', 'בן חתם, מכוח ייפוי כוח כללי שנתן לו אביו הקשיש בפני עורך דין, על מכירת דירה של האב. הקונים טענו שהעסקה מחייבת את האב; בית המשפט המחוזי הורה על בטלותה וחייב את עורך הדין בחלק מהנזק.', 'הערעורים נדחו בעיקרם. בית המשפט עבר על שלוש דרכים חלופיות שבהן פעולת שלוח מחייבת את השולח — הרשאה פנימית, מצג הרשאה כלפי הצד השלישי ואישור בדיעבד — ודחה כל אחת בנפרד, ולכן העסקה בטלה. עוד נקבע שעורך דין סביר פועל להסרת החשד כשמתגלים "סימני התראה". לקח שיטתי: ממצים כל דרך לפני הכרעה.')]
QS=[{'q': 'מה הדבר הראשון שכדאי לקרוא בשאלת "בעיה"?', 'o': ['את שמות הצדדים בלבד', 'את העובדות מהסוף להתחלה', 'את הפסקה הארוכה ביותר', 'את ההוראה שבסוף השאלה — מה בדיוק שואלים ועל מי'], 'c': 3, 'e': 'נכון. ההוראה מגדירה את נקודת המבט, את הצדדים הרלוונטיים ואת התחום, וממקדת את הקריאה של העובדות.'}, {'q': 'מהי "סוגיה" במבחן בעיה?', 'o': ['כל עובדה שמופיעה בשאלה', 'שם של פסק דין', 'סעיף חוק שנלמד בקורס', 'שאלה משפטית שהעובדות מעוררות ושיש בה מחלוקת אפשרית'], 'c': 3, 'e': 'נכון. סוגיה מחברת עובדות לשאלה משפטית שאפשר לטעון לגביה לשני הכיוונים.'}, {'q': 'מהו סדר הדיון המומלץ בסוגיות?', 'o': ['לפי הסדר שבו נלמדו הנושאים בקורס', 'סף (סמכות, התיישנות, מיצוי הליכים), אחר כך גוף העניין, ולבסוף הסעדים', 'רק גוף העניין; הסף אינו נבדק במבחן', 'סעדים, אחר כך גוף העניין, ולבסוף הסף'], 'c': 1, 'e': 'נכון. זה סדר החשיבה של בית משפט: קודם האם אפשר לדון, אחר כך לגופו, ואז מה מקבלים.'}, {'q': 'במבחן לא נאמר אם הודעת הקיבול הגיעה למציע לפני שחזר בו. מה נכון לעשות?', 'o': ['לנתח בתנאי: אם הגיעה לפני — התוצאה X; ואם אחרי — התוצאה Y', 'לכתוב שאי אפשר לענות על השאלה', 'להניח שהגיעה, כי זה נוח לפתרון', 'להתעלם מהסוגיה'], 'c': 0, 'e': 'נכון. ניתוח מותנה מראה שזיהיתם את העובדה החסרה ואת השפעתה על התוצאה.'}, {'q': 'מהו "יישום" טוב?', 'o': ['חזרה על לשון הסעיף במילים אחרות', 'הצמדת עובדה מהשאלה לכל יסוד בכלל, עם הסבר מדוע היסוד מתקיים או לא, והצגת טענות שני הצדדים', 'רשימת פסקי דין רלוונטיים', 'סיכום העובדות בסדר כרונולוגי'], 'c': 1, 'e': 'נכון. זה לב התשובה: חיבור בין העובדה לרכיב, עם "שכן", ושקילת טענות הצדדים.'}, {'q': 'סטודנטית הגיעה למסקנה שלא נכרת חוזה וסיימה את תשובתה. מה החמיצה ככל הנראה?', 'o': ['את הצורך לצטט ספרות', 'טענה חלופית, למשל חוסר תום לב במשא ומתן לפי ס׳ 12, וניתוח הסוגיות הבאות בהנחה שהמסקנה הפוכה', 'את הצורך לחזור על העובדות', 'שום דבר; אם אין חוזה אין תביעה'], 'c': 1, 'e': 'נכון. "וגם אם" מבטיח ניקוד על הסוגיות הבאות ומציג עילה חלופית אפשרית.'}, {'q': 'מדוע חשוב להציג גם את טענות הצד שכנגד במבחן?', 'o': ['כי הבודק מעדיף תשובות ללא מסקנה', 'כי כך התשובה ארוכה יותר', 'כי זה מוכיח שזיהיתם היכן המחלוקת ומחזק את המסקנה', 'אין צורך, מספיק להציג את עמדת הלקוח'], 'c': 2, 'e': 'נכון. הצגת שני הצדדים מראה הבנה של נקודת המחלוקת ומאפשרת להכריע ביניהם בנימוק.'}, {'q': 'בשאלה נכתב: "יעצו לדנה". איך זה משפיע על התשובה?', 'o': ['צריך לכתוב תשובה בגוף ראשון בשם דנה', 'אין השפעה; מנתחים את כל הצדדים באותה מידה', 'צריך לנתח את עמדת דנה, כולל הסיכונים והטענות שיועלו נגדה, ולסיים בהמלצה מעשית', 'צריך לנתח רק את הטענות שלטובתה'], 'c': 2, 'e': 'נכון. ההוראה קובעת נקודת מבט וממילא דורשת גם הערכת סיכונים והמלצה מה לעשות.'}, {'q': 'דנה שלחה הצעה "בתוקף עד יום חמישי", וביום שלישי, לפני שהניצע השיב, הודיעה שהיא חוזרת בה. מה הדין לפי ס׳ 3 לחוק החוזים?', 'o': ['החזרה תקפה אם יש לדנה סיבה טובה', 'החזרה תקפה, כי נמסרה לפני הקיבול', 'החזרה תקפה רק אם נעשתה בכתב', 'החזרה אינה תקפה, כי מציע שקבע מועד לקיבול אינו רשאי לחזור בו לאחר שההצעה נמסרה לניצע'], 'c': 3, 'e': 'נכון. לפי ס׳ 3(ב), קביעת מועד לקיבול הופכת את ההצעה לבלתי חוזרת עד המועד.'}, {'q': 'הניצע השיב בתוך המועד: "מקבל. מעביר את הכסף מחר". האם זו הודעת קיבול לפי ס׳ 5?', 'o': ['כן, אבל רק אם התשלום יבוצע בפועל', 'לא, כי הוסיף תנאי של תשלום מחר', 'כן, ההודעה מעידה על גמירת דעת להתקשר לפי ההצעה, ו"מעביר את הכסף מחר" הוא הודעה על ביצוע ולא תנאי חדש', 'לא, כי קיבול חייב להיות בחתימה'], 'c': 2, 'e': 'נכון. הקיבול מפורש ותואם את ההצעה; תיאור אופן הביצוע אינו משנה את תנאיה.'}, {'q': 'מדוע ס׳ 12 לחוק החוזים מתאים כטענה חלופית בדוגמה הפתורה?', 'o': ['כי הוא חל רק כשנכרת חוזה', 'כי הוא מבטל את החוזה', 'כי גם אם ייקבע שלא נכרת חוזה, חוסר תום לב במשא ומתן מקים חובת פיצוי על הנזק שנגרם', 'כי הוא מחייב את המוכרת למכור את הרכב'], 'c': 2, 'e': 'נכון. זו עילה שאינה תלויה בכריתה, ולכן היא חלופה טבעית לטענה הראשית.'}, {'q': 'לפי תקנה 27 לתקסד״א, מתי מותר לטעון בכתב טענות עובדות חלופיות?', 'o': ['אף פעם', 'כשבעל הדין אימת בתצהיר שהעובדות כהווייתן אינן ידועות לו', 'תמיד, כל עוד הן משפטיות', 'רק בערעור'], 'c': 1, 'e': 'נכון. החריג הוא תצהיר שמאמת שבעל הדין אינו יודע את העובדות כהווייתן.'}, {'q': 'מה נקבע ברע״א 4224/04 בית ששון?', 'o': ['בעל דין רשאי תמיד לשנות טענות בין הליכים', 'בעל דין שטענתו בהליך קודם התקבלה מנוע מלטעון טענה הפוכה בהליך מאוחר, גם בלי להראות שזכה בסוף המשפט', 'השתק שיפוטי חל רק בהליכים פליליים', 'אסור לטעון טענות חלופיות באותו כתב טענות'], 'c': 1, 'e': 'נכון. זה תנאי ההשתק השיפוטי: הטענה הקודמת התקבלה, ואין צורך בניצחון סופי.'}, {'q': 'מה הלקח השיטתי מבג״ץ 2624/97 רונאל?', 'o': ['שבג״ץ תמיד מכריע לגופו של עניין', 'שהרשות חייבת להשיב בתוך יום', 'שאין חובה לפנות לרשות לפני עתירה', 'שיש לבדוק שאלות סף, כמו מיצוי הליכים, לפני הדיון בגוף העניין'], 'c': 3, 'e': 'נכון. נפסק שעל הפונה לתת לרשות שהות סבירה לבחון את פנייתו, ומיצוי הליכים הוא עילת סף.'}, {'q': 'בשאלה מתבקשים לנתח עתירה לבג״ץ נגד פסק דין של בית הדין הארצי לעבודה. מה צריך להופיע בניתוח?', 'o': ['ניתוח מלא מחדש של השאלה כאילו בג״ץ הוא ערכאת ערעור', 'הסבר שבג״ץ אינו מוסמך לבחון פסקי דין של בית הדין לעבודה', 'אמת המידה המצומצמת: התערבות רק בטעות משפטית מהותית ובמקום שהצדק מחייב (עניין חטיב)', 'רק העובדות של פסק הדין'], 'c': 2, 'e': 'נכון. זו ההלכה שנקבעה בעניין חטיב, ובלעדיה הניתוח עונה על שאלה אחרת.'}, {'q': 'מה מדגים עניין הרמן נ׳ עלדור לגבי שיטת פתרון?', 'o': ['שיש למצות את כל הדרכים החלופיות — הרשאה פנימית, מצג הרשאה ואישור בדיעבד — ולדחות או לקבל כל אחת לפני ההכרעה', 'שעורך דין אינו אחראי לעולם בעסקאות מקרקעין', 'שמספיק לבחון דרך אחת שבה שלוח מחייב שולח', 'שייפוי כוח כללי תמיד מתיר כל עסקה'], 'c': 0, 'e': 'נכון. זה מודל לניתוח חלופי ממצה: כל דרך נבחנת בנפרד, ורק אחר כך מכריעים.'}, {'q': 'במבחן של שלוש שעות יש שאלה אחת ששווה 50% מהציון. כמה זמן כדאי להקצות לה בערך?', 'o': ['אותו זמן כמו לכל שאלה אחרת', 'כל הזמן שנדרש עד שתושלם', 'כשעה וחצי, ומתוכה כחמישית לקריאה ולתכנון', 'עשרים דקות, כי היא הראשונה'], 'c': 2, 'e': 'נכון. חלוקה לפי ניקוד שומרת זמן לכל השאלות, ותכנון מראש מונע חזרות ושכחת סוגיות.'}, {'q': 'סטודנט כתב חצי עמוד על ההיסטוריה של חוק החוזים בתשובה לשאלת בעיה, בלי קשר לעובדות. מה הבעיה?', 'o': ['"שפיכת חומר": ידע שאינו מיושם על העובדות אינו מזכה בנקודות ואוכל זמן', 'צריך היה לכתוב עמוד שלם', 'היה צריך לכתוב זאת בסוף התשובה', 'אין בעיה; זה מראה ידע'], 'c': 0, 'e': 'נכון. הכלל מוצג במידה שנדרשת ליישום, והזמן מוקדש לחיבור בין הכלל לעובדות.'}, {'q': 'איזו שאלה צריכה להופיע תמיד בסוף ניתוח של עילה בשאלת "מה דין התביעה"?', 'o': ['מי כתב את החוק', 'מה דעתי האישית על הצדדים', 'האם השאלה הוגנת', 'איזה סעד יקבל התובע, ובאיזה היקף'], 'c': 3, 'e': 'נכון. תביעה נועדה לקבל סעד, ובלי לנתח אותו התשובה אינה שלמה.'}, {'q': 'בשאלה אמריקאית הופיעה התשובה: "מציע רשאי בכל מקרה לחזור בו מהצעתו לפני שהתקבלה". מה צריך להדליק נורה?', 'o': ['המילה "מציע"', 'המילה "הצעה"', 'הביטוי "בכל מקרה", שמתעלם מהחריג של ס׳ 3(ב) להצעה עם מועד לקיבול', 'המילה "לפני"'], 'c': 2, 'e': 'נכון. מילים מוחלטות כמו "תמיד" ו"בכל מקרה" הן סימן לבדוק חריגים, וכאן החריג של ס׳ 3(ב) הופך את המשפט לשגוי.'}]
MAR=[]
